<?php
namespace App\Game; use App\DB;
final class MissionService { public const MISSIONS=['earn_10k'=>['emoji'=>'🎯','name'=>'اولین ۱۰,۰۰۰ دلار','target'=>10000,'metric'=>'earned_total','reward_cash'=>2000,'reward_xp'=>500,'min_level'=>1],'work_5'=>['emoji'=>'🔧','name'=>'۵ بار سر کار برو','target'=>5,'metric'=>'work_count','reward_cash'=>500,'reward_xp'=>200,'min_level'=>1],'buy_item'=>['emoji'=>'🎒','name'=>'اولین خرید از فروشگاه','target'=>1,'metric'=>'item_buys','reward_cash'=>300,'reward_xp'=>150,'min_level'=>1],'transfer_1'=>['emoji'=>'💸','name'=>'اولین انتقال پول','target'=>1,'metric'=>'transfers','reward_cash'=>300,'reward_xp'=>150,'min_level'=>1],'biz_upgrade'=>['emoji'=>'📈','name'=>'کسب‌وکار رو ارتقا بده','target'=>1,'metric'=>'biz_upgrades','reward_cash'=>4000,'reward_xp'=>800,'min_level'=>3],'level_5'=>['emoji'=>'⭐','name'=>'به لول ۵ برس','target'=>5,'metric'=>'level','reward_cash'=>3000,'reward_xp'=>0,'min_level'=>1]];
 public static function listFor(array $u):array{$s=DB::pdo()->prepare('SELECT * FROM player_missions WHERE user_id=?');$s->execute([$u['id']]);$rows=[];foreach($s->fetchAll() as $r)$rows[$r['mission_key']]=$r;$out=[];foreach(self::MISSIONS as $k=>$m){if((int)$u['level']<$m['min_level'])continue;$r=$rows[$k]??[];$out[$k]=['meta'=>$m,'progress'=>(int)($r['progress']??0),'done'=>(int)($r['done']??0),'claimed'=>(int)($r['claimed']??0)];}return $out;}
 public static function progress(array $u,string $metric,int $amount):array{$msgs=[];foreach(self::MISSIONS as $k=>$m){if($m['metric']!==$metric)continue;$s=DB::pdo()->prepare('SELECT * FROM player_missions WHERE user_id=? AND mission_key=?');$s->execute([$u['id'],$k]);$r=$s->fetch();if($r&&(int)$r['done'])continue;$p=in_array($metric,['level','earned_total'],true)?$amount:(int)($r['progress']??0)+$amount;$done=$p>=$m['target']?1:0;if($r)DB::pdo()->prepare('UPDATE player_missions SET progress=?,done=? WHERE user_id=? AND mission_key=?')->execute([$p,$done,$u['id'],$k]);else DB::pdo()->prepare('INSERT INTO player_missions (user_id,mission_key,progress,done,assigned_at) VALUES (?,?,?,?,?)')->execute([$u['id'],$k,$p,$done,time()]);if($done)$msgs[]='✅ مأموریت انجام شد: <b>'.$m['name'].'</b>'; }return $msgs;}
 public static function claim(array $u,string $k):?string{$m=self::MISSIONS[$k]??null;if(!$m)return null;$s=DB::pdo()->prepare('SELECT * FROM player_missions WHERE user_id=? AND mission_key=?');$s->execute([$u['id'],$k]);$r=$s->fetch();if(!$r||!(int)$r['done']||(int)$r['claimed'])return null;DB::pdo()->prepare('UPDATE player_missions SET claimed=1 WHERE user_id=? AND mission_key=? AND claimed=0')->execute([$u['id'],$k]);if($m['reward_cash'])EconomyService::earn($u,$m['reward_cash'],'جایزه مأموریت');$xp=$m['reward_xp']?PlayerService::addXp($u,$m['reward_xp']):'';return "🎁 <b>{$m['name']}</b>\n💰 +".number_format($m['reward_cash']).' دلار'.($m['reward_xp']?"\n⭐ +{$m['reward_xp']} XP":'').$xp;}}
